{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.cluster_category_size_depth as WITH unique_pincode_mapping AS ( SELECT PINCODE, STATENAME, ROW_NUMBER() OVER (PARTITION BY PINCODE ORDER BY STATENAME) AS rn FROM snitch_db.maplemonk.PINCODE_DISTRICT_MAPPING ), pincode_mapping AS ( SELECT a.PINCODE, UPPER(a.SKU) AS SKU, a.SHIPPING_QUANTITY, a.RETURN_QUANTITY, a.CANCELLED_QUANTITY, b.STATENAME FROM SNITCH_DB.MAPLEMONK.UNICOMMERCE_FACT_ITEMS_SNITCH AS a LEFT JOIN unique_pincode_mapping AS b ON CAST(a.PINCODE AS VARCHAR) = CAST(b.PINCODE AS VARCHAR) WHERE b.rn = 1 ), sales_online AS ( SELECT a.SKU, a.STATENAME, SUM(COALESCE(a.SHIPPING_QUANTITY, 0) + COALESCE(a.RETURN_QUANTITY, 0) + COALESCE(a.CANCELLED_QUANTITY, 0)) AS ONLINE_SALES FROM pincode_mapping AS a GROUP BY a.SKU, a.STATENAME ), online_mapping AS ( SELECT b.SKU, UPPER(b.SKU_GROUP) AS SKU_GROUP, ROW_NUMBER() OVER (PARTITION BY b.SKU ORDER BY b.SKU_GROUP ASC) AS rn FROM SNITCH_DB.MAPLEMONK.UNICOMMERCE_FACT_ITEMS_SNITCH b ), online_skugrp_mapping AS ( SELECT s.SKU, s.STATENAME AS STATE, s.ONLINE_SALES, r.SKU_GROUP FROM sales_online s LEFT JOIN online_mapping r ON s.SKU = r.SKU WHERE r.rn = 1 ), online_category_mapping AS ( SELECT UPPER(SKU_GROUP) AS SKU_GROUP, UPPER(CATEGORY) AS CATEGORY FROM ( SELECT UPPER (SKU_GROUP) AS SKU_GROUP, UPPER(CATEGORY) AS CATEGORY, ROW_NUMBER() OVER (PARTITION BY SKU_GROUP ORDER BY UPPER(CATEGORY) ASC) AS rn FROM snitch_db.maplemonk.CATEGORY_JOURNEY ) ranked WHERE rn = 1 ), online_data AS ( SELECT sm.SKU AS SKU, sm.ONLINE_SALES AS ONLINE_SALES, sm.SKU_GROUP AS SKU_GROUP, sm.STATE AS STATE, cm.CATEGORY AS CATEGORY FROM online_skugrp_mapping sm LEFT JOIN ONLINE_CATEGORY_MAPPING cm ON sm.SKU_GROUP = cm.SKU_GROUP ), online_size_table AS ( SELECT SKU, STATE, CATEGORY, ONLINE_SALES AS SALES, CASE WHEN SKU LIKE \'SN%\' OR SKU LIKE \'4MSFR%\' OR SKU LIKE \'BP%\' THEN \'NA\' WHEN SKU LIKE \'SH%\' THEN CASE WHEN SKU LIKE \'%-39\' THEN \'XS\' WHEN SKU LIKE \'%-40\' THEN \'S\' WHEN SKU LIKE \'%-41\' THEN \'M\' WHEN SKU LIKE \'%-42\' THEN \'L\' WHEN SKU LIKE \'%-43\' THEN \'XL\' WHEN SKU LIKE \'%-44\' THEN \'XXL\' WHEN SKU LIKE \'%-45\' THEN \'3XL\' END WHEN SKU LIKE \'4M%\' THEN CASE WHEN SKU LIKE \'%-XS\' OR SKU LIKE \'%-28\' THEN \'XS\' WHEN SKU LIKE \'%-S\' OR SKU LIKE \'%-30\' THEN \'S\' WHEN SKU LIKE \'%-M\' OR SKU LIKE \'%-32\' THEN \'M\' WHEN SKU LIKE \'%-L\' OR SKU LIKE \'%-34\' THEN \'L\' WHEN SKU LIKE \'%-XL\' OR SKU LIKE \'%-36\' THEN \'XL\' WHEN SKU LIKE \'%-XXL\' OR SKU LIKE \'%-38\' THEN \'XXL\' WHEN SKU LIKE \'%-3XL\' OR SKU LIKE \'%-40\' THEN \'3XL\' WHEN SKU LIKE \'%-4XL\' OR SKU LIKE \'%-42\' THEN \'4XL\' WHEN SKU LIKE \'%-5XL\' OR SKU LIKE \'%-44\' THEN \'5XL\' WHEN SKU LIKE \'%-6XL\' OR SKU LIKE \'%-46\' THEN \'6XL\' WHEN SKU LIKE \'%-7XL\' OR SKU LIKE \'%-48\' THEN \'7XL\' WHEN SKU LIKE \'%-8XL\' OR SKU LIKE \'%-50\' THEN \'8XL\' ELSE CASE WHEN POSITION(\'-\' IN SKU) > 0 THEN UPPER(TRIM(SUBSTRING(SKU, LEN(SKU) - CHARINDEX(\'-\', REVERSE(SKU)) + 2))) ELSE \'NA\' END END ELSE CASE WHEN POSITION(\'-\' IN SKU) > 0 THEN UPPER(TRIM(SUBSTRING(SKU, LEN(SKU) - CHARINDEX(\'-\', REVERSE(SKU)) + 2))) ELSE \'NA\' END END AS SIZE FROM online_data ), unique_branch_mapping AS ( SELECT a.\"STORE CODE\" AS BRANCH_CODE, UPPER(a.\"CLUSTER\") AS STATE, ROW_NUMBER() OVER (PARTITION BY a.\"STORE CODE\" ORDER BY UPPER(a.\"CLUSTER\")) AS rn FROM snitch_db.maplemonk.SHEET1 AS a ), branch_mapping AS ( SELECT a.BRANCH_CODE, UPPER(a.SKU) AS SKU, a.SHIPPING_QUANTITY, a.RETURN_QUANTITY, a.CANCELLED_QUANTITY, b.STATE FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE AS a LEFT JOIN unique_branch_mapping AS b ON b.BRANCH_CODE = a.BRANCH_CODE WHERE b.rn = 1 ), sales_offline AS ( SELECT UPPER(a.SKU) AS SKU, UPPER(a.STATE) AS STATE, SUM(COALESCE(a.SHIPPING_QUANTITY, 0) + COALESCE(a.RETURN_QUANTITY, 0) + COALESCE(a.CANCELLED_QUANTITY, 0)) AS OFFLINE_SALES FROM branch_mapping AS a GROUP BY UPPER(a.SKU), UPPER(a.STATE) ), offline_mapping AS ( SELECT UPPER(b.SKU) AS SKU, UPPER(b.SKU_GROUP) AS SKU_GROUP, ROW_NUMBER() OVER (PARTITION BY b.SKU ORDER BY UPPER(b.SKU_GROUP) ASC) AS rn FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE b ), offline_skugrp_mapping AS ( SELECT s.SKU, s.STATE, s.OFFLINE_SALES, r.SKU_GROUP FROM sales_offline s LEFT JOIN offline_mapping r ON s.SKU = r.SKU WHERE r.rn = 1 ), OFFLINE_CATEGORY_MAPPING AS ( SELECT SKU_GROUP, UPPER(CATEGORY) AS CATEGORY FROM ( SELECT SKU_GROUP, UPPER(CATEGORY) AS CATEGORY, ROW_NUMBER() OVER (PARTITION BY SKU_GROUP ORDER BY UPPER(CATEGORY) ASC) AS rn FROM snitch_db.maplemonk.CATEGORY_JOURNEY ) ranked WHERE rn = 1 ), offline_data AS ( SELECT sm.SKU AS SKU, sm.OFFLINE_SALES AS OFFLINE_SALES, sm.SKU_GROUP AS SKU_GROUP, sm.STATE AS STATE, cm.CATEGORY AS CATEGORY FROM offline_skugrp_mapping sm LEFT JOIN OFFLINE_CATEGORY_MAPPING cm ON sm.SKU_GROUP = cm.SKU_GROUP WHERE cm.CATEGORY IS NOT NULL ), offline_size_table AS ( SELECT SKU, STATE, CATEGORY, OFFLINE_SALES AS SALES, CASE WHEN SKU LIKE \'SN%\' OR SKU LIKE \'4MSFR%\' OR SKU LIKE \'BP%\' THEN \'NA\' WHEN SKU LIKE \'SH%\' THEN CASE WHEN SKU LIKE \'%-39\' THEN \'XS\' WHEN SKU LIKE \'%-40\' THEN \'S\' WHEN SKU LIKE \'%-41\' THEN \'M\' WHEN SKU LIKE \'%-42\' THEN \'L\' WHEN SKU LIKE \'%-43\' THEN \'XL\' WHEN SKU LIKE \'%-44\' THEN \'XXL\' WHEN SKU LIKE \'%-45\' THEN \'3XL\' END WHEN SKU LIKE \'4M%\' THEN CASE WHEN SKU LIKE \'%-XS\' OR SKU LIKE \'%-28\' THEN \'XS\' WHEN SKU LIKE \'%-S\' OR SKU LIKE \'%-30\' THEN \'S\' WHEN SKU LIKE \'%-M\' OR SKU LIKE \'%-32\' THEN \'M\' WHEN SKU LIKE \'%-L\' OR SKU LIKE \'%-34\' THEN \'L\' WHEN SKU LIKE \'%-XL\' OR SKU LIKE \'%-36\' THEN \'XL\' WHEN SKU LIKE \'%-XXL\' OR SKU LIKE \'%-38\' THEN \'XXL\' WHEN SKU LIKE \'%-3XL\' OR SKU LIKE \'%-40\' THEN \'3XL\' WHEN SKU LIKE \'%-4XL\' OR SKU LIKE \'%-42\' THEN \'4XL\' WHEN SKU LIKE \'%-5XL\' OR SKU LIKE \'%-44\' THEN \'5XL\' WHEN SKU LIKE \'%-6XL\' OR SKU LIKE \'%-46\' THEN \'6XL\' WHEN SKU LIKE \'%-7XL\' OR SKU LIKE \'%-48\' THEN \'7XL\' WHEN SKU LIKE \'%-8XL\' OR SKU LIKE \'%-50\' THEN \'8XL\' ELSE CASE WHEN POSITION(\'-\' IN SKU) > 0 THEN UPPER(TRIM(SPLIT_PART(SKU, \'-\', -1))) ELSE \'NA\' END END ELSE CASE WHEN POSITION(\'-\' IN SKU) > 0 THEN UPPER(TRIM(SPLIT_PART(SKU, \'-\', -1))) ELSE \'NA\' END END AS SIZE FROM offline_data ), Combined_Size AS ( SELECT state, category, size, sales FROM online_size_table UNION ALL SELECT state, category, size, sales FROM offline_size_table ), final_size_table AS ( SELECT STATE, CATEGORY, SALES, CASE WHEN SIZE IN (\'28\', \'XS\') THEN \'XS\' WHEN SIZE IN (\'30\', \'S\') THEN \'S\' WHEN SIZE IN (\'32\', \'M\') THEN \'M\' WHEN SIZE IN (\'34\', \'L\') THEN \'L\' WHEN SIZE IN (\'36\', \'XL\') THEN \'XL\' WHEN SIZE IN (\'38\', \'XXL\') THEN \'XXL\' WHEN SIZE IN (\'40\', \'3XL\', \'XXXL\') THEN \'3XL\' WHEN SIZE IN (\'42\', \'XXXXL\', \'4XL\') THEN \'4XL\' WHEN SIZE IN (\'44\', \'5XL\') THEN \'5XL\' WHEN SIZE IN (\'46\', \'6XL\') THEN \'6XL\' WHEN SIZE IN (\'48\', \'7XL\') THEN \'7XL\' WHEN SIZE IN (\'50\', \'8XL\') THEN \'8XL\' ELSE \'NA\' END AS SIZE FROM combined_size ), size_sum as ( SELECT state, category, size, SUM(sales) AS total_sales FROM final_size_table GROUP BY state, category, size ), total_size_sum as ( select state, category, sum(total_sales) as total from size_sum group by state, category ), size_perc_table AS ( SELECT a.total, a.state, a.category, b.total_sales, b.size, b.total_sales / NULLIF(COALESCE(a.total, 0), 0) AS size_perc FROM size_sum AS b JOIN total_size_sum AS a ON a.state = b.state AND a.category = b.category ), final_data AS ( SELECT p.state, p.category, p.XS_PERC, p.S_PERC, p.M_PERC, p.L_PERC, p.XL_PERC, p.XXL_PERC, p.\"3XL_PERC\", p.\"4XL_PERC\", p.\"5XL_PERC\", p.\"6XL_PERC\", p.\"7XL_PERC\", p.\"8XL_PERC\", p.NA_PERC, s.\"STORE CODE\" AS BRANCH_CODE, s.\"STORE NAME\", s.DEPT_IDEAL FROM ( SELECT state, category, SUM(CASE WHEN size = \'XS\' THEN size_perc ELSE 0 END) AS XS_PERC, SUM(CASE WHEN size = \'S\' THEN size_perc ELSE 0 END) AS S_PERC, SUM(CASE WHEN size = \'M\' THEN size_perc ELSE 0 END) AS M_PERC, SUM(CASE WHEN size = \'L\' THEN size_perc ELSE 0 END) AS L_PERC, SUM(CASE WHEN size = \'XL\' THEN size_perc ELSE 0 END) AS XL_PERC, SUM(CASE WHEN size = \'XXL\' THEN size_perc ELSE 0 END) AS XXL_PERC, SUM(CASE WHEN size = \'3XL\' THEN size_perc ELSE 0 END) AS \"3XL_PERC\", SUM(CASE WHEN size = \'4XL\' THEN size_perc ELSE 0 END) AS \"4XL_PERC\", SUM(CASE WHEN size = \'5XL\' THEN size_perc ELSE 0 END) AS \"5XL_PERC\", SUM(CASE WHEN size = \'6XL\' THEN size_perc ELSE 0 END) AS \"6XL_PERC\", SUM(CASE WHEN size = \'7XL\' THEN size_perc ELSE 0 END) AS \"7XL_PERC\", SUM(CASE WHEN size = \'8XL\' THEN size_perc ELSE 0 END) AS \"8XL_PERC\", SUM(CASE WHEN size = \'NA\' THEN size_perc ELSE 0 END) AS NA_PERC FROM size_perc_table GROUP BY state, category ) AS p JOIN ( SELECT a.\"STORE CODE\", a.\"STORE NAME\", a.\"CLUSTER\" AS STATE, a.\"IDEAL_DEPTH\" AS DEPT_IDEAL FROM snitch_db.maplemonk.sheet1 AS a ) AS s ON UPPER(p.state) = UPPER(s.state) ) SELECT BRANCH_CODE, STATE, CATEGORY, \"STORE NAME\", DEPT_IDEAL, XS_PERC, S_PERC, M_PERC, L_PERC, XL_PERC, XXL_PERC, \"3XL_PERC\", \"4XL_PERC\", \"5XL_PERC\", \"6XL_PERC\", \"7XL_PERC\", \"8XL_PERC\", ROUND(XS_PERC * DEPT_IDEAL) AS XS_DEPTH, ROUND(S_PERC * DEPT_IDEAL) AS S_DEPTH, ROUND(M_PERC * DEPT_IDEAL) AS M_DEPTH, ROUND(L_PERC * DEPT_IDEAL) AS L_DEPTH, ROUND(XL_PERC * DEPT_IDEAL) AS XL_DEPTH, ROUND(XXL_PERC * DEPT_IDEAL) AS XXL_DEPTH, ROUND(\"3XL_PERC\" * DEPT_IDEAL) AS \"3XL_DEPTH\", ROUND(\"4XL_PERC\" * DEPT_IDEAL) AS \"4XL_DEPTH\", ROUND(\"5XL_PERC\" * DEPT_IDEAL) AS \"5XL_DEPTH\", ROUND(\"6XL_PERC\" * DEPT_IDEAL) AS \"6XL_DEPTH\", ROUND(\"7XL_PERC\" * DEPT_IDEAL) AS \"7XL_DEPTH\", ROUND(\"8XL_PERC\" * DEPT_IDEAL) AS \"8XL_DEPTH\" FROM FINAL_DATA; create or replace table snitch_db.maplemonk.store_category_delta as with branch_details as ( select a.store as branch_name, a.store_code::varchar as branch_code, a.category, a.CLUSTER, b.\"BASE STOCK\" as base_stock, a.category_mix, a.category_mix*b.\"BASE STOCK\" as category_base_stock from snitch_db.maplemonk.category_mix a left join snitch_db.maplemonk.master_file b on a.store = b.\"STORE NAME\" and a.store_code::varchar = b.\"STORE CODE\"::varchar and a.cluster = b.cluster ), inventory as ( select branch_code::varchar as branch_code, new_category as category, sum(inventory) as inventory, sum(jit_qty) as jit_qty, sum(sales_last_7_days) as sales_7d, round(sum(sales_last_7_days)/7,0) as ros_7d from snitch_db.maplemonk.offline_master group by 1,2 ), lead_time as ( select BRANCH_CODE_PRIORITY::varchar as branch_code, lead_time from snitch_db.maplemonk.google_sheet_fresh_priority ) select a.*, ifnull(b.inventory,0) as inventory, ifnull(b.jit_qty,0) as jit_qty, ifnull(b.sales_7d,0) as sales_7d, ifnull(b.ros_7d,0) as ros_7d, ifnull(c.lead_time,0) as lead_time, ifnull((b.inventory+b.jit_qty+(0.3*b.ros_7d)-(b.ros_7d*c.lead_time)),0) as total_inventory, ifnull((round(greatest((a.category_base_stock) - (b.inventory+b.jit_qty+(0.3*b.ros_7d)-(b.ros_7d*c.lead_time)),0),0)),0) as delta from branch_details a left join inventory b on a.branch_code = b.branch_code and a.category = b.category left join lead_time c on a.branch_code = c.branch_code; create or replace table snitch_db.maplemonk.STORE_METAFIELD_DELTA2 as WITH base AS ( SELECT BRANCH_CODE AS BRANCH_CODE , NEW_CATEGORY AS NEW_CATEGORY , COLLAR_NEW , MATERIAL_NEW , SLEEVE_TYPE , FIT , DESIGNS , COALESCE(INVENTORY, 0) + COALESCE(JIT_QTY, 0) AS stock , COALESCE(TOTAL_SALES, 0) AS sales FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER ), totals AS ( SELECT BRANCH_CODE AS BRANCH_CODE , NEW_CATEGORY AS NEW_CATEGORY , SUM(stock) AS cat_stock_total , SUM(sales) AS cat_sales_total FROM base GROUP BY BRANCH_CODE , NEW_CATEGORY ) SELECT b.BRANCH_CODE AS BRANCH_CODE , b.NEW_CATEGORY AS NEW_CATEGORY , b.COLLAR_NEW AS COLLAR_NEW , b.MATERIAL_NEW AS MATERIAL_NEW , b.SLEEVE_TYPE AS SLEEVE_TYPE , b.FIT AS FIT , b.DESIGNS AS DESIGNS , SUM(b.stock) AS \"Inventory+JIT_Qty\" , SUM(b.stock) AS \"Stock\" , SUM(b.sales) AS \"Sales\" , CASE WHEN t.cat_stock_total = 0 THEN 0 ELSE (SUM(b.stock) / t.cat_stock_total) END AS \"Stock% at category level\" , CASE WHEN t.cat_sales_total = 0 THEN 0 ELSE (SUM(b.sales) / t.cat_sales_total) END AS \"Sales% at category level\" , CASE WHEN t.cat_stock_total = 0 OR t.cat_sales_total = 0 OR SUM(b.stock) = 0 THEN 0 ELSE GREATEST( 0, ( ( SUM(b.sales) / NULLIF(t.cat_sales_total, 0) ) / ( SUM(b.stock) / NULLIF(t.cat_stock_total, 0) ) ) * SUM(b.stock) - SUM(b.stock) ) END AS \"meta_delta\" FROM base b JOIN totals t ON b.BRANCH_CODE = t.BRANCH_CODE AND b.NEW_CATEGORY = t.NEW_CATEGORY GROUP BY b.BRANCH_CODE , b.NEW_CATEGORY , b.COLLAR_NEW , b.MATERIAL_NEW , b.SLEEVE_TYPE , b.FIT , b.DESIGNS , t.cat_stock_total , t.cat_sales_total ORDER BY b.BRANCH_CODE , b.NEW_CATEGORY , b.COLLAR_NEW , b.MATERIAL_NEW , b.SLEEVE_TYPE , b.FIT , b.DESIGNS ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            